n=22; bg=5
grid=[[bg]*n for _ in range(n)]
objects=[(3,0,8,9),(5,17,2,4),(9,4,2,3),(12,10,8,1),(16,0,8,2),(17,17,2,9)]
for r,c,border,inside in objects:
    for i in range(5):
        for j in range(5):
            grid[r+i][c+j]=inside if 1<=i<=3 and 1<=j<=3 else border
print('\n'.join(' '.join(map(str,row)) for row in grid))
import json
print(json.dumps({'action':'submit','grid':grid}))

